const data = $input.first().json;
const results = data.results || [];

if (!results.length) {
  return [{
    json: {
      hasDeal: false,
      dealId: ''
    }
  }];
}

return [{
  json: {
    hasDeal: true,
    dealId: results[0].toObjectId
  }
}];

const itemsIn = $input.all();

if (!itemsIn.length) {
  return [];
}

function stageScore(stage) {
  const map = {
    'Appointment Scheduled': 10,
    'Qualified To Buy': 20,
    'Presentation Scheduled': 30,
    'Decision Maker Bought-In': 40,
    'Contract Sent': 50,
    'Closed Won': 100,
    'Closed Lost': -100,
  };
  return map[stage] ?? 0;
}

const deals = itemsIn.map(i => i.json);

const openDeals = deals.filter(d => {
  const stage = d.dealstage || d.properties?.dealstage || '';
  return stage !== 'Closed Won' && stage !== 'Closed Lost';
});

if (!openDeals.length) {
  return [];
}

openDeals.sort((a, b) => {
  const aStage = a.dealstage || a.properties?.dealstage || '';
  const bStage = b.dealstage || b.properties?.dealstage || '';

  const scoreDiff = stageScore(bStage) - stageScore(aStage);
  if (scoreDiff !== 0) return scoreDiff;

  const aDate = new Date(a.hs_lastmodifieddate || a.properties?.hs_lastmodifieddate || 0).getTime();
  const bDate = new Date(b.hs_lastmodifieddate || b.properties?.hs_lastmodifieddate || 0).getTime();
  return bDate - aDate;
});

return [{ json: openDeals[0] }];

const thread = $items("Gmail_Get_Thread", 0, 0)[0].json;
const meta = $items("Code_Extract_Reply_Metadata", 0, 0)[0].json;

// Mets ici toutes tes adresses d’envoi possibles
const myEmails = [
  'remicahen@gmail.com',
  'your_alias@magrid.education'
].map(e => e.toLowerCase());

// ---------- Helpers ----------
function getHeader(headers, name) {
  if (!Array.isArray(headers)) return '';
  const found = headers.find(
    h => (h.name || '').toLowerCase() === name.toLowerCase()
  );
  return found?.value || '';
}

function decodeBase64Url(str) {
  if (!str || typeof str !== 'string') return '';
  try {
    str = str.replace(/-/g, '+').replace(/_/g, '/');
    while (str.length % 4 !== 0) str += '=';
    return Buffer.from(str, 'base64').toString('utf8');
  } catch {
    return '';
  }
}

function extractBodyFromPayload(payload) {
  if (!payload) return '';

  if (payload.mimeType === 'text/plain' && payload.body?.data) {
    return decodeBase64Url(payload.body.data);
  }

  if (payload.body?.data) {
    return decodeBase64Url(payload.body.data);
  }

  if (Array.isArray(payload.parts)) {
    for (const part of payload.parts) {
      if (part.mimeType === 'text/plain' && part.body?.data) {
        return decodeBase64Url(part.body.data);
      }
    }

    for (const part of payload.parts) {
      const nested = extractBodyFromPayload(part);
      if (nested) return nested;
    }
  }

  return '';
}

function cleanBody(text) {
  if (!text) return '';

  let t = text.replace(/\r/g, '');

  t = t.split('\n').filter(line => {
    const trimmed = line.trim();
    return !trimmed.startsWith('>');
  }).join('\n');

  const cutPatterns = [
    /^On .+wrote:$/im,
    /^From: .+$/im,
    /^Sent: .+$/im,
    /^De : .+$/im,
    /^Envoyé : .+$/im,
    /^Subject: .+$/im,
    /^Objet : .+$/im,
    /^-----Original Message-----$/im,
    /^________________________________$/im,
  ];

  for (const pattern of cutPatterns) {
    const match = t.match(pattern);
    if (match && typeof match.index === 'number') {
      t = t.slice(0, match.index).trim();
      break;
    }
  }

  t = t.replace(/\n{3,}/g, '\n\n').trim();

  if (t.length > 2500) {
    t = t.slice(0, 2500).trim();
  }

  return t;
}

function normalizeEmailAddress(fromHeader) {
  if (!fromHeader) return '';
  const match = fromHeader.match(/<([^>]+)>/);
  return (match ? match[1] : fromHeader).trim().toLowerCase();
}

function isInternalSender(fromHeader, myEmails) {
  const email = normalizeEmailAddress(fromHeader);
  return myEmails.includes(email);
}

function toIsoDate(internalDate, dateHeader) {
  if (internalDate) {
    const ts = Number(internalDate);
    if (!Number.isNaN(ts) && ts > 0) {
      return new Date(ts).toISOString();
    }
  }
  if (dateHeader) {
    const d = new Date(dateHeader);
    if (!Number.isNaN(d.getTime())) {
      return d.toISOString();
    }
  }
  return null;
}

// ---------- Main ----------
const messages = Array.isArray(thread.messages) ? thread.messages : [];

if (!messages.length) {
  return [{
    json: {
      thread_id: thread.id || meta.gmail_thread_id || '',
      message_count: 0,
      last_inbound_from: '',
      last_inbound_date: null,
      last_inbound_subject: meta.original_subject || '',
      last_inbound_message: '',
      last_outbound_date: null,
      last_outbound_message: '',
      conversation_status: 'unknown',
      thread_summary_for_ai: 'No messages found in thread.'
    }
  }];
}

const normalizedMessages = messages.map(m => {
  const headers = m.payload?.headers || [];
  const from = getHeader(headers, 'From');
  const subject = getHeader(headers, 'Subject');
  const dateHeader = getHeader(headers, 'Date');

  const rawBody = extractBodyFromPayload(m.payload) || m.snippet || '';
  const cleanText = cleanBody(rawBody);
  const isoDate = toIsoDate(m.internalDate, dateHeader);

  return {
    id: m.id || '',
    threadId: m.threadId || thread.id || '',
    from,
    fromEmail: normalizeEmailAddress(from),
    subject,
    date: isoDate,
    internalDate: Number(m.internalDate || 0),
    body: cleanText,
    snippet: m.snippet || '',
    isInternal: isInternalSender(from, myEmails),
  };
});

normalizedMessages.sort((a, b) => a.internalDate - b.internalDate);

const inboundMessages = normalizedMessages.filter(m => !m.isInternal);
const outboundMessages = normalizedMessages.filter(m => m.isInternal);

const lastInbound = inboundMessages.length ? inboundMessages[inboundMessages.length - 1] : null;
const lastOutbound = outboundMessages.length ? outboundMessages[outboundMessages.length - 1] : null;

let conversationStatus = 'unknown';

if (lastInbound && lastOutbound) {
  conversationStatus =
    lastInbound.internalDate > lastOutbound.internalDate
      ? 'waiting_reply_from_us'
      : 'waiting_reply_from_them';
} else if (lastInbound) {
  conversationStatus = 'waiting_reply_from_us';
} else if (lastOutbound) {
  conversationStatus = 'waiting_reply_from_them';
}

const recentMessagesForAI = normalizedMessages
  .slice(-4)
  .map(m => {
    const role = m.isInternal ? 'OUTBOUND' : 'INBOUND';
    const body = (m.body || m.snippet || '').slice(0, 800);
    return `${role} | ${m.date || 'unknown date'} | ${m.from}\n${body}`;
  })
  .join('\n\n---\n\n');

const threadSummaryForAI = [
  `Thread ID: ${thread.id || meta.gmail_thread_id || ''}`,
  `Message count: ${normalizedMessages.length}`,
  `Conversation status: ${conversationStatus}`,
  lastInbound ? `Last inbound from: ${lastInbound.from}` : `Last inbound from: none`,
  lastInbound ? `Last inbound date: ${lastInbound.date}` : `Last inbound date: none`,
  lastOutbound ? `Last outbound date: ${lastOutbound.date}` : `Last outbound date: none`,
  '',
  'Recent messages:',
  recentMessagesForAI
].join('\n');

return [{
  json: {
    thread_id: thread.id || meta.gmail_thread_id || '',
    message_count: normalizedMessages.length,
    last_inbound_from: lastInbound?.from || '',
    last_inbound_date: lastInbound?.date || null,
    last_inbound_subject: lastInbound?.subject || meta.original_subject || '',
    last_inbound_message: lastInbound?.body || lastInbound?.snippet || '',
    last_outbound_date: lastOutbound?.date || null,
    last_outbound_message: lastOutbound?.body || lastOutbound?.snippet || '',
    conversation_status: conversationStatus,
    thread_summary_for_ai: threadSummaryForAI
  }
}];

const raw =
  $json.output?.[0]?.content?.[0]?.text || "";

if (!raw) {
  throw new Error("Réponse OpenAI vide");
}

let content = raw.trim();

if (content.startsWith("```")) {
  content = content
    .replace(/^```json\s*/i, "")
    .replace(/^```\s*/i, "")
    .replace(/\s*```$/i, "")
    .trim();
}

let parsed;

try {
  parsed = JSON.parse(content);
} catch (e) {
  throw new Error(`OpenAI response is not valid JSON. Raw content: ${content}`);
}

const subject = parsed.subject || parsed.email_subject || "";
const body = parsed.body || parsed.email_body || "";

if (!subject || !body) {
  throw new Error("Sujet ou corps d’email manquant");
}

return [
  {
    json: {
      subject,
      body
    }
  }
];

