const input = $input.first().json;

// Essaie plusieurs champs possibles venant du Gmail Trigger
const rawFrom =
  input.From ||
  input.from ||
  input.sender ||
  input.fromEmail ||
  input.headers?.from ||
  '';

const subject =
  input.subject ||
  '';

const threadId =
  input.threadId ||
  input.gmail_thread_id ||
  input.thread_id ||
  '';

const messageId =
  input.id ||
  input.messageId ||
  input.gmail_message_id ||
  '';

const receivedAt =
  input.internalDate ||
  input.date ||
  new Date().toISOString();

const snippet =
  input.snippet ||
  '';

function extractEmail(raw) {
  if (!raw) return '';
  const match = String(raw).match(/<([^>]+)>/);
  return (match ? match[1] : String(raw)).trim().toLowerCase();
}

const fromEmail = extractEmail(rawFrom);

return [{
  json: {
    from_raw: rawFrom,
    from_email: fromEmail,
    gmail_message_id: messageId,
    gmail_thread_id: threadId,
    subject,
    received_at: receivedAt,
    snippet
  }
}];

const current = $input.first().json || {};
const normalize = $node["Code_Normalize_Email"].json || {};
const thread = $node["Code_Thread_Summary"].json || {};
const lang = $node["Code_Detect_Language"].json || {};

const replyMode = current.aiReplyMode || current.replyMode || "generic_professional_reply";
const draftPriority = current.draftPriority || "normal";
const draftDecisionReason = current.draftDecisionReason || "";

const stakeholderType = current.stakeholderType || "generic_prospect";
const stakeholderConfidence = current.stakeholderConfidence || "low";
const stakeholderReason = current.stakeholderReason || "";
const isInstitutional = current.isInstitutional === true;

const threadSummary =
  thread.thread_summary_for_ai ||
  current.thread_summary_for_ai ||
  current.thread_summary ||
  current.threadSummary ||
  "";

const originalSubject =
  thread.last_inbound_subject ||
  current.last_inbound_subject ||
  current.subject ||
  current.email_subject ||
  "";

const senderRaw = thread.last_inbound_from || current.last_inbound_from || "";
const senderName =
  current.senderName ||
  current.from_name ||
  current.sender_name ||
  senderRaw ||
  "";

const senderEmail =
  normalize.from_email ||
  current.senderEmail ||
  current.from_email ||
  current.sender ||
  "";

const senderDomain = current.senderDomain || "";
const senderCompanyGuess = current.senderCompanyGuess || "";

const hasDeal = current.hasDeal === true || current.has_deal === true;

const dealName = current.deal_name || current.dealname || "";
const dealStage = current.deal_stage || current.dealstage || "";
const pipeline = current.pipeline || "";
const amount = current.amount || "";
const closeDate = current.close_date || "";
const ownerName = current.owner_name || "";

const companyName = current.company || current.company_name || "";
const contactName = current.contact_name || senderName || "";

const tone = current.tone || "professional";
const targetLength = current.targetLength || "medium";
const ctaType = current.ctaType || "general";

let toneInstructions = "";
let lengthInstructions = "";
let ctaInstructions = "";
let modeInstructions = "";
let dealStageInstructions = "";
let stakeholderInstructions = "";

// Tone instructions
if (tone === "formal_institutional") {
  toneInstructions = `
- Use formal, precise, institutionally appropriate language.
- Avoid startup-style enthusiasm, hype, or casual wording.
- Sound credible, structured, and respectful.
- Keep the writing suitable for ministries, governments, NGOs, school groups, or senior educational stakeholders.
`;
} else if (tone === "commercial_professional") {
  toneInstructions = `
- Use professional sales language, but remain measured and credible.
- Be helpful, clear, and oriented toward progress.
- Avoid sounding pushy or overly promotional.
`;
} else if (tone === "warm_professional") {
  toneInstructions = `
- Use a warm, polite, professional tone.
- Keep the message natural and easy to read.
`;
} else {
  toneInstructions = `
- Use a professional, clear, neutral tone.
- Keep the message polished and business-appropriate.
`;
}

// Length instructions
if (targetLength === "short") {
  lengthInstructions = `
- Keep the email short.
- Aim for a concise reply with no unnecessary background.
`;
} else if (targetLength === "medium") {
  lengthInstructions = `
- Keep the email moderately concise.
- Include enough substance to be useful, but avoid unnecessary length.
`;
} else {
  lengthInstructions = `
- Write a complete but still readable email.
`;
}

// CTA instructions
if (ctaType === "none") {
  ctaInstructions = `
- Do not force a next step.
- Acknowledge appropriately and close politely.
`;
} else if (ctaType === "propose_meeting") {
  ctaInstructions = `
- Move the conversation toward scheduling.
- If appropriate, suggest next steps or invite the recipient to share availability.
`;
} else if (ctaType === "share_information") {
  ctaInstructions = `
- Answer the request clearly.
- Where relevant, propose a logical next step after sharing information.
`;
} else if (ctaType === "advance_opportunity") {
  ctaInstructions = `
- Help move the opportunity forward.
- End with a concrete and sensible commercial next step.
`;
} else if (ctaType === "institutional_next_step") {
  ctaInstructions = `
- Suggest an appropriate institutional next step.
- This may include a call, a short exchange, a pilot discussion, or sharing formal materials.
- Keep the proposed next step respectful and proportionate.
`;
} else {
  ctaInstructions = `
- End with a useful and professional next step when appropriate.
`;
}

// Reply mode instructions
if (replyMode === "short_acknowledgment") {
  modeInstructions = `
- This is a short acknowledgment.
- Keep the response brief, polite, and clean.
- Do not over-explain.
`;
} else if (replyMode === "meeting_scheduling") {
  modeInstructions = `
- This is a scheduling-related reply.
- Be practical, clear, and concise.
- Focus on confirming, proposing, or organizing the meeting.
`;
} else if (replyMode === "information_request") {
  modeInstructions = `
- This is an information request.
- Answer clearly and in a structured way.
- Be helpful and relevant.
`;
} else if (replyMode === "proposal_follow_up") {
  modeInstructions = `
- This is a commercial or proposal follow-up.
- Reinforce relevance, maintain momentum, and guide toward a concrete next step.
`;
} else if (replyMode === "institutional_reply") {
  modeInstructions = `
- This is an institutional reply.
- Use formal, structured wording appropriate for public or mission-driven stakeholders.
- When useful, emphasize educational value, implementation relevance, inclusion, evidence, and long-term impact.
`;
} else {
  modeInstructions = `
- This is a generic professional reply.
- Keep the response balanced, clear, and context-appropriate.
`;
}

// Deal-stage-aware instructions
const ds = String(dealStage || "").toLowerCase();

if (ds.includes("appointment") || ds.includes("qualified") || ds.includes("new")) {
  dealStageInstructions = `
- The opportunity appears to be at an early stage.
- The reply should build trust, clarify relevance, and open the door to a focused next exchange.
- Avoid sounding too advanced or assumptive.
`;
} else if (ds.includes("presentation") || ds.includes("demo") || ds.includes("meeting")) {
  dealStageInstructions = `
- The opportunity appears to be in an exploration or presentation phase.
- The reply should support evaluation, clarity, and engagement.
- Reinforce relevance and help structure the next conversation.
`;
} else if (ds.includes("proposal") || ds.includes("quote") || ds.includes("pricing")) {
  dealStageInstructions = `
- The opportunity appears to be in a proposal or pricing phase.
- The reply should be precise, reassuring, and decision-supportive.
- Reduce ambiguity and help the recipient move toward an internal decision.
`;
} else if (ds.includes("pilot") || ds.includes("test")) {
  dealStageInstructions = `
- The opportunity appears to be in a pilot or validation phase.
- The reply should emphasize implementation clarity, expected outcomes, support, and learning value.
`;
} else if (ds.includes("procurement") || ds.includes("legal") || ds.includes("contract")) {
  dealStageInstructions = `
- The opportunity appears to be in a formal procurement, legal, or contracting phase.
- The reply should be careful, precise, and formal.
- Avoid unnecessary marketing language.
`;
} else if (hasDeal) {
  dealStageInstructions = `
- There is an active opportunity in the CRM.
- The reply should take the deal context into account and support progress in a measured way.
`;
}

// Stakeholder instructions
if (stakeholderType === "government_or_ministry") {
  stakeholderInstructions = `
- The recipient appears to be a government, ministry, or public authority stakeholder.
- Use formal, institutional, respectful wording.
- Emphasize educational relevance, implementation clarity, and credibility.
- Avoid startup-style or overly commercial phrasing.
`;
} else if (stakeholderType === "ngo_or_foundation") {
  stakeholderInstructions = `
- The recipient appears to be from an NGO or foundation context.
- Use mission-aligned, thoughtful, professional language.
- Emphasize impact, inclusion, and practical implementation value.
`;
} else if (stakeholderType === "school_group_or_academic") {
  stakeholderInstructions = `
- The recipient appears to be from a school group or academic context.
- Use clear educational language and practical implementation framing.
`;
} else if (stakeholderType === "partner_or_reseller") {
  stakeholderInstructions = `
- The recipient appears to be a partner, reseller, or distributor.
- Use collaborative, commercially clear wording.
`;
} else if (stakeholderType === "specialized_education_center") {
  stakeholderInstructions = `
- The recipient appears to be in a specialized education or inclusion context.
- Use precise, respectful language and emphasize relevance for diverse learners.
`;
}

const languageInstructions =
  lang.detected_language === 'fr'
    ? `
- Write the email in French.
`
    : lang.detected_language === 'es'
    ? `
- Write the email in Spanish.
`
    : `
- Write the email in English.
`;

const businessInstructions = `
- The email must be professional and credible in an education-sector context.
- Where relevant, position the company in a measured way, not as aggressive sales language.
- For institutional audiences, prefer wording related to educational relevance, inclusion, implementation, evidence, scalability, and practical next steps.
- Do not invent facts, metrics, partnerships, endorsements, pilots, or government relationships that are not present in the provided context.
- Do not mention internal CRM fields explicitly.
- Do not include a signature.
- Do not use markdown.
- Return only raw JSON with exactly this structure:
{
  "subject": "...",
  "body": "..."
}
`;

const crmContext = hasDeal
  ? `
CRM CONTEXT
- Active deal: yes
- Deal name: ${dealName}
- Deal stage: ${dealStage}
- Pipeline: ${pipeline}
- Amount: ${amount}
- Close date: ${closeDate}
- Owner: ${ownerName}
- Company: ${companyName}
- Contact: ${contactName}
`
  : `
CRM CONTEXT
- Active deal: no confirmed active deal
- Company: ${companyName}
- Contact: ${contactName}
`;

const finalPrompt = `
You are drafting a reply email for Rémi Cahen at Magrid.

EMAIL METADATA
- Original subject: ${originalSubject}
- Sender name: ${senderName}
- Sender email: ${senderEmail}
- Sender domain: ${senderDomain}
- Sender organization guess: ${senderCompanyGuess}
- Sender language: ${lang.detected_language_label || 'English'}

STAKEHOLDER CONTEXT
- Stakeholder type: ${stakeholderType}
- Stakeholder confidence: ${stakeholderConfidence}
- Stakeholder reason: ${stakeholderReason}
- Institutional account: ${isInstitutional}

REPLY STRATEGY
- Reply mode: ${replyMode}
- AI decision reason: ${draftDecisionReason}
- Priority: ${draftPriority}
- Tone: ${tone}
- Target length: ${targetLength}
- CTA type: ${ctaType}

${languageInstructions}
${toneInstructions}
${lengthInstructions}
${ctaInstructions}
${modeInstructions}
${dealStageInstructions}
${stakeholderInstructions}
${businessInstructions}

THREAD SUMMARY
${threadSummary}

LATEST INBOUND MESSAGE
${thread.last_inbound_message || ''}

${crmContext}

TASK
Draft the most appropriate reply email based on the thread and CRM context.

OUTPUT RULES
- Return only raw JSON.
- Use exactly:
{
  "subject": "...",
  "body": "..."
}
- The subject must be suitable for a reply.
- The body must be ready to send after signature is added separately.
`.trim();

return [{
  json: {
    ...current,
    contact_email: normalize.from_email || '',
    gmail_thread_id: normalize.gmail_thread_id || '',
    has_deal: hasDeal,
    deal_name: dealName,
    deal_stage: dealStage,
    pipeline,
    amount,
    detected_language: lang.detected_language || 'en',
    detected_language_label: lang.detected_language_label || 'English',
    last_inbound_from: thread.last_inbound_from || '',
    last_inbound_date: thread.last_inbound_date || '',
    last_inbound_subject: thread.last_inbound_subject || '',
    last_inbound_message: thread.last_inbound_message || '',
    last_outbound_date: thread.last_outbound_date || '',
    last_outbound_message: thread.last_outbound_message || '',
    conversation_status: thread.conversation_status || '',
    thread_summary_for_ai: threadSummary,
    finalPrompt
  }
}];

const subject = ($json.subject || $json.email_subject || "").toLowerCase();
const body = ($json.body || $json.email_body || $json.thread_summary || "").toLowerCase();
const fullText = `${subject}\n${body}`.trim();

const hasAny = (arr) => arr.some(term => fullText.includes(term));

let replyMode = "generic_professional_reply";
let tone = "professional";
let targetLength = "medium";
let ctaType = "general";
let classificationReason = "default";

// 1. very short acknowledgment
if (
  fullText.length < 120 &&
  hasAny(["thanks", "thank you", "merci", "bien reçu", "received", "noted", "perfect", "ok", "okay"])
) {
  replyMode = "short_acknowledgment";
  tone = "warm_professional";
  targetLength = "short";
  ctaType = "none";
  classificationReason = "short_acknowledgment";
}

// 2. meeting scheduling
else if (
  hasAny([
    "schedule", "meeting", "call", "zoom", "teams", "availability",
    "available", "next week", "calendar", "time slot", "book a time"
  ])
) {
  replyMode = "meeting_scheduling";
  tone = "professional";
  targetLength = "short";
  ctaType = "propose_meeting";
  classificationReason = "meeting_scheduling";
}

// 3. information request
else if (
