      threadId,
      mimeMessage: mime,
      raw: toBase64Url(mime),
    }
  }
];

const thread = $json;

function getHeader(message, name) {
  const headers = message?.payload?.headers || [];
  const found = headers.find(
    h => (h.name || "").toLowerCase() === name.toLowerCase()
  );
  return found?.value || "";
}

function extractEmail(addressLine = "") {
  const match = addressLine.match(/<([^>]+)>/);
  if (match) return match[1].trim();
  return addressLine.trim();
}

const messages = thread.messages || [];
const lastMessage = messages[messages.length - 1] || {};

const subject = getHeader(lastMessage, "Subject");
const messageId = getHeader(lastMessage, "Message-ID") || getHeader(lastMessage, "Message-Id");
const references = getHeader(lastMessage, "References");
const replyTo = getHeader(lastMessage, "Reply-To");
const from = getHeader(lastMessage, "From");

const replyEmail = extractEmail(replyTo || from);

return [
  {
    json: {
      gmail_thread_id: thread.id || thread.threadId || "",
      original_subject: subject || "",
      incoming_message_id: messageId || "",
      existing_references: references || "",
      reply_to_email: replyEmail || "",
      raw_from: from || "",
      raw_reply_to: replyTo || "",
    }
  }
];
